      const L = data.lessons[i];
      if (!L || !L.lesson) continue;
      // Per-RESOURCE marks ("1.1|worksheet") so BOTH the calendar grey-out AND
      // the per-resource Done button ("Completed") follow the login across
      // devices. Fall back to a generic "<topic>|server" mark (greys the lesson
      // only) for an older server payload that lacks selfDoneArtifacts.
      const arts = Array.isArray(L.selfDoneArtifacts) ? L.selfDoneArtifacts : [];
