// CALENDAR_FOCUS -- roll a lesson topic up to ''|'partial'|'done' from the
// student's OWN completion marks (the object getStudentMarks() returns from
// apstats_desk_marks_<email>). recordProgress() stamps a `ts` field on every
// Done; a visit-only mark (recordLinkVisit) has no `ts`. So 'done' = at least
// one resource of this lesson was marked Done, 'partial' = visited but nothing
// done yet, '' = untouched. This is the LOCAL signal: unlike the /donow
// ledger it reflects the signed-in student (or, in Preview-as-student, the
// teacher). It is distinct from the REGISTRY lesson-readiness that feeds the
// status dot -- that is teacher-side "materials posted", not student work.
function localLessonState(topic, marks) {
  if (topic === 'B-Work' || topic === 'B-Break' || topic === 'E-Break') return '';
  if (!topic || !marks || typeof marks !== 'object') return '';
  const members = typeof groupTopics==='function' ? groupTopics(topic) : [topic];
  if(members.length>1){
    const states=members.map(member=>localLessonState(member,marks));
    if(states.every(state=>state==='done'))return 'done';
    return states.some(Boolean)?'partial':'';
  }
  const prefix = topic + '|';
  let anyVisit = false, anyDone = false;
  for (const key in marks) {
    if (key.indexOf(prefix) !== 0) continue;
    const m = marks[key];
    if (!m || typeof m !== 'object') continue;
    anyVisit = true;
    if (m.ts) anyDone = true;
  }
  // 'done' requires the lesson's GATE artifacts (worksheet + Blooket) to ALL be
  // Done — not just any single artifact (e.g. the quiz alone). Reuses the same
  // oracle as the sequential unlock gate (_isLessonComplete) so the greying, the
  // next-up cell, the Do-Now pointer and the unlock all AGREE. A lesson with no
  // gate artifacts (quiz-only / review day) falls back to "any artifact Done".
  // Fails OPEN to the old lenient behavior if the registry isn't available.
  let reg = null;
  try { reg = (typeof getRegistryEntry === 'function') ? getRegistryEntry(topic) : null; } catch (_) {}
  const gurls = (reg && reg.urls) || {};
  const hasGate = !!(gurls.worksheet || gurls.blooket);
  if (hasGate) {
    if (typeof _isLessonComplete === 'function' && _isLessonComplete(topic, marks)) return 'done';
    return anyVisit ? 'partial' : '';
  }
  if (anyDone) return 'done';
  return anyVisit ? 'partial' : '';
}

// CALENDAR_FOCUS -- the next-up lesson (the synthwave cell): the FIRST entry in
// orderedTopics (chronological) that is a real lesson -- topic shaped N.N, so
// review / off / exam cells are skipped -- AND is not 'done' per the student's
// local marks. Returns the topic string, or null when every lesson is done.
// Same local signal as the greyscale, so a done lesson is never also next-up.
function calNextUpTopic(orderedTopics, marks) {
  if (!Array.isArray(orderedTopics)) return null;
  for (const t of orderedTopics) {
    if (typeof t !== 'string' || !/^\d+\.\d+/.test(t)) continue;
    if (localLessonState(t, marks) !== 'done') return t;
  }
  return null;
}

