// openDayGrade(dateStr) — opens the Day Grade modal for a calendar date.
// dateStr: display string like "Sep 3" (used in header).
// Data: looks up _gradeLessonsCache (populated by renderDoNowGrades).
function openDayGrade(dateStr) {
    var ov = document.getElementById('day-grade-overlay');
    var header = document.getElementById('day-grade-header');
    var body = document.getElementById('day-grade-body');
    if (!ov || !header || !body) return;

    // Set header text.
    header.textContent = 'Day grade — ' + dateStr;

    // Clear body safely.
    while (body.firstChild) body.removeChild(body.firstChild);

    // Find lessons scheduled for this date.
    var lessons = _gradeLessonsCache;
    var matching = [];
    if (Array.isArray(lessons)) {
        for (var i = 0; i < lessons.length; i++) {
            var l = lessons[i];
            // Match by display date string (B or E period label matches dateStr).
            // We also check the calendar date via data stored on the cell.
            // The dateStr format is e.g. "Apr 6" — match against the lesson's
            // due dates. Both B and E are checked.
            var due = l.due || {};
            var bDate = due.B;
            var eDate = due.E;
            // Format a date string from YYYY-MM-DD to match the calendar cell dateStr.
            function fmtDate(d) {
                if (!d) return null;
                var parts = d.split('-');
                if (parts.length < 3) return null;
                var months = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
                var m = parseInt(parts[1], 10) - 1;
                return months[m] + ' ' + parseInt(parts[2], 10);
            }
            var bFmt = fmtDate(bDate);
            var eFmt = fmtDate(eDate);
            if (bFmt === dateStr || eFmt === dateStr) {
                matching.push(l);
            }
        }
    }

    if (matching.length === 0) {
        var empty = document.createElement('div');
        empty.textContent = 'No lessons due this day.';
        empty.style.color = '#888';
        empty.style.fontStyle = 'italic';
        body.appendChild(empty);
    } else {
        for (var j = 0; j < matching.length; j++) {
            var lesson = matching[j];
            var card = document.createElement('div');
            card.style.cssText = 'border:1px solid #ccc;padding:6px 8px;margin-bottom:6px;background:#fafafa';

            var titleEl = document.createElement('div');
            titleEl.style.cssText = 'font-family:Chicago,monospace;font-size:11px;font-weight:bold;margin-bottom:3px';
            titleEl.textContent = cedLabel(lesson.lessonKey).text;
            card.appendChild(titleEl);

            var gradeEl = document.createElement('div');
            gradeEl.style.marginBottom = '3px';
            var lgVal = lesson.lessonGrade;
            var gradeText = lgVal != null ? (Math.round(lgVal * 10) / 10).toFixed(1) : '—';
            var glabel = document.createElement('span');
            glabel.textContent = 'Lesson grade: ';
            glabel.style.fontWeight = 'bold';
            var gval = document.createElement('span');
            gval.textContent = gradeText;
            gradeEl.appendChild(glabel);
            gradeEl.appendChild(gval);
            if (lesson.exitBonus) {
                var exitLabel = document.createElement('span');
                exitLabel.textContent = ' (+' + lesson.exitBonus + ' exit ticket)';
                gradeEl.appendChild(exitLabel);
            }
            card.appendChild(gradeEl);

            // Per-lesson Blooket score (graded warm-up), when recorded.
            if (lesson.blooket != null) {
                var blEl = document.createElement('div');
                blEl.style.marginBottom = '3px';
                var blLabel = document.createElement('span');
                blLabel.textContent = 'Blooket: ';
                blLabel.style.fontWeight = 'bold';
                var blVal = document.createElement('span');
                blVal.textContent = (Math.round(lesson.blooket * 10) / 10).toFixed(1) + '%';
                blEl.appendChild(blLabel);
                blEl.appendChild(blVal);
                card.appendChild(blEl);
            }

            var items = lesson.items || { frq: [], quiz: [], worksheet: [] };
            var frqs = Array.isArray(items.frq) ? items.frq : [];
            var quizzes = Array.isArray(items.quiz) ? items.quiz : [];
            var worksheets = Array.isArray(items.worksheet) ? items.worksheet : [];

            var gradedFrqs = frqs.filter(function (f) { return f.score != null; });
            var frqMean = gradedFrqs.length > 0
                ? (gradedFrqs.reduce(function (s, f) { return s + f.score; }, 0) / gradedFrqs.length)
                : null;

            var detailEl = document.createElement('div');
            detailEl.style.color = '#555';
            detailEl.style.fontSize = '10px';

            var parts = [];
            if (frqs.length > 0) {
                var frqStr = 'FRQs graded: ' + gradedFrqs.length + '/' + frqs.length;
                if (frqMean != null) frqStr += ' (mean ' + Math.round(frqMean * 10) / 10 + ')';
                parts.push(frqStr);
            } else {
                parts.push('FRQs: not taken');
            }
            // Quiz: show the score % that feeds the grade (lesson.Q, 0..100),
            // falling back to credit earned / items when Q isn't computed yet.
            if (lesson.Q != null) {
                parts.push('Quiz: ' + (Math.round(lesson.Q * 10) / 10) + '%');
            } else if (quizzes.length > 0) {
                // A count shown as a score sums credit: a half-credit retry reads as a half.
                // No "correct" label: 1½/2 is credit, and only one of those items is correct.
                var creditSum = quizzes.reduce(function (s, q) {
                    return s + (typeof q.credit === 'number' ? q.credit : (q.correct ? 1 : 0));
                }, 0);
                parts.push('Quiz: ' + _quizCreditText(creditSum) + '/' + quizzes.length);
            } else {
                parts.push('Quiz: not taken');
            }
            if (worksheets.length > 0 || lesson.Cws != null) {
                // W1: items.worksheet is now blank-level score rows; show the
                // worksheet score (Cws) rather than a misleading completion count.
                var wsN = worksheets.length;
                var wsLabel = wsN + ' blank' + (wsN === 1 ? '' : 's');
                if (lesson.Cws != null) {
                    parts.push('Worksheet blanks: ' + (Math.round(lesson.Cws * 10) / 10) + '% (' + wsLabel + ')');
                    if (typeof lesson.W === 'number') parts.push('AI reflections: ' + (Math.round(lesson.W * 10) / 10) + '%');
                    if (typeof lesson.lessonGradeNoQuiz === 'number') parts.push('Follow-Along grade: ' + (Math.round(lesson.lessonGradeNoQuiz * 10) / 10) + '%');
                } else {
                    parts.push('Worksheet: ' + wsLabel + ' attempted');
                }
            }

            detailEl.textContent = parts.join(' · ');
            card.appendChild(detailEl);

            body.appendChild(card);
        }
    }

    ov.style.display = 'block';
    _attachDayGradeKeyHandler();
}

