function bumpUsage(id) {
    try {
        var counts = JSON.parse(localStorage.getItem('ap-roadmap-icon-usage') || '{}');
        counts[id] = (counts[id] || 0) + 1;
        localStorage.setItem('ap-roadmap-icon-usage', JSON.stringify(counts));
    } catch(e) {}
}








// The URL an app window opens (SOLO_DOOR_SPEC §5: the calculator is no longer an app window).
function appLaunchUrl(app, id) {
    if (id === 'week') {
        var teacher = (typeof _deskIsTeacher === 'function') && _deskIsTeacher();
        return app.url + (teacher ? '?ced=1' : '?ced=0');
    }
    // SLIPS_V2_SPEC §3: the teacher gets the DOK app's "Print slips" panel; students the plain URL.
    if (id === 'dok') {
        var isTeacher = (typeof _deskIsTeacher === 'function') && _deskIsTeacher();
        return isTeacher ? app.url + '?teacher=1' : app.url;
    }
    return app.url;
}

function openApp(id) {
    var app = APP_REGISTRY[id];
    if (!app) return;
    bumpUsage(id);
    MacSFX.play(app.sfx, 0.5);
    var overlay = document.getElementById('app-' + id + '-overlay');
    var iframe = document.getElementById('app-' + id + '-frame');
    var win = overlay.querySelector('.app-window');
    if (!iframe.src || iframe.src === 'about:blank' || iframe.src === window.location.href) {
        iframe.src = appLaunchUrl(app, id);
    }
    // Reset position to centered
    win.style.left = '50%';
    win.style.top = '50%';
    win.style.transform = 'translate(-50%, -50%)';
    overlay.style.display = 'block';
    // Embedded apps are keyboard-driven and nothing else ever hands the
    // iframe focus (desk-roster-alignment-spec §1.4). Best-effort only.
    try { iframe.focus(); } catch (e) {}
}

// Close = fully destroy (clear iframe)
// Open in new window: pop the app out to a real browser tab/window.
function popOutApp(id) {
    var app = APP_REGISTRY[id];
    if (!app) return;
    try { if (typeof MacSFX !== 'undefined') MacSFX.play('click', 0.3); } catch (e) {}
    window.open(appLaunchUrl(app, id), '_blank', 'noopener');
}

function destroyApp(id) {
    if (typeof MacSFX !== 'undefined') MacSFX.play('click', 0.3);
    if (id === 'teachertools' && typeof destroyTeacherTools === 'function') {
        destroyTeacherTools();
        return;
    }
    if (id === 'wallet' && typeof _clearStudentWalletCeremony === 'function') _clearStudentWalletCeremony();
    var overlay = document.getElementById('app-' + id + '-overlay');
    var iframe = document.getElementById('app-' + id + '-frame');
    var win = overlay.querySelector('.app-window');
    overlay.style.display = 'none';
    if (iframe) iframe.src = 'about:blank';
    win.classList.remove('maximized');
}

// Minimize = animate to icon, keep iframe alive
function minimizeApp(id) {
    if (typeof MacSFX !== 'undefined') MacSFX.play('click', 0.3);
    if (id === 'wallet' && typeof _clearStudentWalletCeremony === 'function') _clearStudentWalletCeremony();
    var overlay = document.getElementById('app-' + id + '-overlay');
    var win = overlay.querySelector('.app-window');
    var icon = document.querySelector('.app-icon[data-app="' + id + '"]');
    if (!icon) { overlay.style.display = 'none'; return; }

    var winRect = win.getBoundingClientRect();
    var iconRect = icon.getBoundingClientRect();

    // Create outline element
    var outline = document.createElement('div');
    outline.className = 'minimize-outline';
    outline.style.left = winRect.left + 'px';
    outline.style.top = winRect.top + 'px';
    outline.style.width = winRect.width + 'px';
    outline.style.height = winRect.height + 'px';
    document.body.appendChild(outline);

    // Hide window immediately
    overlay.style.display = 'none';

    // Animate outline to icon
    requestAnimationFrame(function() {
        outline.style.left = iconRect.left + 'px';
        outline.style.top = iconRect.top + 'px';
        outline.style.width = iconRect.width + 'px';
        outline.style.height = iconRect.height + 'px';
        outline.classList.add('shrink');
        outline.addEventListener('transitionend', function() {
            outline.remove();
        });
    });
}

/* ── Trainer bridge (desk-roster-alignment-spec §1.3 + §5.4) ──
   Answers the embedded Formula Lab's identity handshake and surfaces
   its achievement events. Additive and fail-open: every branch is wrapped
   so a throw can never affect the rest of the Desk. */

// One toast at a time -- a new trainer event replaces the visible toast.
var _trainerToastEl = null;
var _trainerToastTimer = null;

function _showTrainerToast(msg) {
    try {
        if (_trainerToastEl) _trainerToastEl.remove();
        if (_trainerToastTimer) clearTimeout(_trainerToastTimer);
        var t = document.createElement('div');
        t.className = 'chicago';
        t.style.cssText = 'position:fixed;bottom:18px;right:18px;z-index:9999;' +
            'background:var(--platinum);color:var(--black);border:1px solid var(--black);' +
            'box-shadow:inset 1px 1px 0 0 var(--plat-hi),inset -1px -1px 0 0 var(--plat-lo),2px 2px 0 0 var(--black);' +
            'border-radius:2px;padding:8px 14px;font-size:12px;max-width:320px;pointer-events:none;';
        t.textContent = msg;
        document.body.appendChild(t);
        _trainerToastEl = t;
        _trainerToastTimer = setTimeout(function() {
            try { t.remove(); } catch (e) {}
            _trainerToastEl = null;
            _trainerToastTimer = null;
        }, 4000);
        // (no beep for a passive toast; 2026-08-19)
    } catch (e) {}
}

// Append to the capped trainer-event log. Malformed stored value resets to [].
function _appendTrainerEvent(entry) {
    try {
        var log = [];
        try { log = JSON.parse(localStorage.getItem('trainer-events.v1') || '[]'); } catch (e) {}
        if (!Array.isArray(log)) log = [];
        log.push(entry);
        if (log.length > 50) log = log.slice(-50);
        localStorage.setItem('trainer-events.v1', JSON.stringify(log));
    } catch (e) {}
}

function _trainerEventMessage(entry) {
    var labels = {
        'run-complete': 'run complete',
        'daily-mission': 'daily mission done',
        'quest-claim': 'quest claimed'
    };
    var msg = 'Formula Lab: ' + (labels[entry.event] || entry.event || 'achievement');
    if (entry.topicId) msg += ' on ' + entry.topicId;
    if (entry.accuracy > 0) msg += ' — ' + Math.round(entry.accuracy * 100) + '%';
    return msg;
}

window.addEventListener('message', function (event) {
    if (event.origin !== 'https://tmux-trainer.vercel.app') return;
    // Bind to the launched iframe instance — never answer arbitrary
    // windows that merely share the origin (popups, other tabs):
    var frame = document.getElementById('app-formulas-frame');
    if (!frame || event.source !== frame.contentWindow) return;
    var data = event.data || {};

    if (data.type === 'roster-identity-request') {
        try {
            var session = (window.rosterClient && rosterClient.current()) || null;
            if (session) session = Object.assign({}, session, { token: rosterClient.token() });
            event.source.postMessage({ type: 'roster-identity', session: session },
                'https://tmux-trainer.vercel.app');
        } catch (e) {}
        return;
    }

    if (data.type === 'trainer-event') {
        try {
            var entry = {
                event: String(data.event || ''),
                deckId: String(data.deckId || ''),
                topicId: data.topicId ? String(data.topicId) : null,
                score: Number(data.score) || 0,
                accuracy: Number(data.accuracy) || 0,
                ts: Number(data.ts) || Date.now()
            };
            _appendTrainerEvent(entry);
            _showTrainerToast(_trainerEventMessage(entry));
        } catch (e) {}
        return;
    }
});

