        ov.style.cssText = 'position:fixed;inset:0;z-index:100002;background:rgba(0,0,0,.82);display:none;flex-direction:column;align-items:center;justify-content:center;cursor:pointer;padding:16px';
        ov.innerHTML = '<div style="background:#fff;padding:22px;border-radius:10px;display:flex;align-items:center;justify-content:center"><div id="big-qr-host"></div></div>'
            + '<div style="color:#fff;margin-top:14px;font-family:Geneva,Verdana,sans-serif;font-size:13px">tap anywhere to close</div>';
        ov.addEventListener('click', function(){ ov.style.display = 'none'; });
